#include <string>
#include <vector>
using namespace std;

class Solution {
public:
    string abbreviateProduct(int left, int right) {
        // Store the exact product in base 10^9, least significant block first.
        const long long BASE = 1000000000LL;
        vector<long long> blocks(1, 1);

        for (int value = left; value <= right; ++value) {
            long long carry = 0;
            for (long long& block : blocks) {
                long long current = block * value + carry;
                block = current % BASE;
                carry = current / BASE;
            }
            while (carry > 0) {
                blocks.push_back(carry % BASE);
                carry /= BASE;
            }
        }

        string product = to_string(blocks.back());
        for (int i = static_cast<int>(blocks.size()) - 2; i >= 0; --i) {
            string block = to_string(blocks[i]);
            product += string(9 - block.size(), '0') + block;
        }

        int trailingZeros = 0;
        while (product.back() == '0') {
            product.pop_back();
            ++trailingZeros;
        }

        if (product.size() > 10) {
            product = product.substr(0, 5) + "..." +
                      product.substr(product.size() - 5);
        }

        return product + "e" + to_string(trailingZeros);
    }
};

